# Hindi / Gujarati text for History Ch 5 lesson, sections 4 (second block) to 7.
TEXT_B = {
 "s4.mania.title": ("पढ़ने का जुनून और फ़्रांसीसी क्रांति", "વાંચનનો જુવાળ અને ફ્રેન્ચ ક્રાંતિ"),
 "s4.mania.body": (
  "**पढ़ने का जुनून:** 17वीं और 18वीं सदी में चर्चों द्वारा गाँवों में स्कूल खोलने से यूरोप में साक्षरता बढ़ी; 18वीं सदी के अंत तक यूरोप के कुछ भागों में साक्षरता **60 से 80 प्रतिशत** तक पहुँच गई।\n"
  "- पुस्तक-विक्रेता **फेरीवालों** को रखते थे जो गाँव-गाँव घूमकर छोटी किताबें बेचते: पंचांग, गाथागीत, लोककथाएँ। इंग्लैंड में **पेनी चैपबुक्स** (एक पेनी की किताबें) **चैपमैन** नामक फेरीवाले बेचते थे। फ़्रांस में ***बिब्लियोथीक ब्ल्यू*** घटिया काग़ज़ पर छपी, **नीली जिल्द** वाली सस्ती छोटी किताबें थीं।\n"
  "- 18वीं सदी की शुरुआत से **पत्रिकाओं** में युद्धों और व्यापार की ख़बरों के साथ मनोरंजन भी होता था। वैज्ञानिकों और दार्शनिकों के विचार सुलभ हुए: **आइज़क न्यूटन** की खोजें छपीं, और **टॉमस पेन, वॉल्तेयर और ज्याँ ज़ाक रूसो** के लेख ख़ूब छपे और पढ़े गए।\n\n"
  "**'तो निरंकुशवादियो, अब काँपने का समय आ गया है!'** 18वीं सदी के मध्य तक लोग मानने लगे थे कि किताबें प्रगति और ज्ञानोदय फैला सकती हैं और समाज को निरंकुशता से मुक्त कर सकती हैं। 18वीं सदी के फ़्रांसीसी उपन्यासकार **लुई-सेबेस्तिएँ मर्सिए** ने घोषणा की: *'छापाख़ाना प्रगति का सबसे ताक़तवर औज़ार है, इससे बन रही जनमत की आँधी में निरंकुशवाद उड़ जाएगा।'* "
  "उन्होंने लिखा: ***'तो निरंकुशवादियो, अब काँपने का समय आ गया है! आभासी लेखक के क़लम के ज़ोर के आगे तुम हिल उठोगे!'*** (निरंकुशवादी यानी राजतंत्र और चर्च जैसी निरंकुश संस्थाएँ)।\n\n"
  "**मुद्रण संस्कृति और फ़्रांसीसी क्रांति:** इतिहासकार तीन तर्क देते हैं:\n1. मुद्रण ने **ज्ञानोदय के चिंतकों** (वॉल्तेयर, रूसो) के विचारों को लोकप्रिय बनाया, जिन्होंने परंपरा, अंधविश्वास और निरंकुशता की आलोचना की और तर्क के शासन की वकालत की; उन्होंने चर्च की पवित्र सत्ता और राज्य की निरंकुश शक्ति पर हमला किया।\n"
  "2. मुद्रण ने **वाद-विवाद और संवाद की नई संस्कृति** को जन्म दिया: तर्क की शक्ति से परिचित जनता ने सभी मूल्यों, मानदंडों और संस्थाओं का पुनर्मूल्यांकन किया।\n"
  "3. **1780 के दशक** तक राजशाही और उसकी नैतिकता का मज़ाक़ उड़ाने वाले साहित्य, **कार्टूनों और कैरिकेचरों** की बाढ़ आ गई, जो दिखाते थे कि राजशाही भोग-विलास में डूबी है जबकि आम जनता कष्ट झेल रही है; इससे राजशाही के विरुद्ध शत्रुता फैली।\n\n"
  "पर मुद्रण सीधे-सीधे लोगों के विचार नहीं गढ़ता: लोग शाही और चर्च का प्रचार भी पढ़ते थे, और कुछ विचार मानते तो कुछ नकार देते थे। हाँ, मुद्रण ने **अलग ढंग से सोचने की संभावना** ज़रूर खोल दी।",
  "**વાંચનનો જુવાળ:** 17મી અને 18મી સદીમાં ચર્ચોએ ગામડાંમાં શાળાઓ ખોલી તેથી યુરોપમાં સાક્ષરતા વધી; 18મી સદીના અંત સુધીમાં યુરોપના કેટલાક ભાગોમાં સાક્ષરતા **60થી 80 ટકા** સુધી પહોંચી.\n"
  "- પુસ્તકવિક્રેતાઓ **ફેરિયાઓ** રાખતા જે ગામે ગામ ફરીને નાનાં પુસ્તકો વેચતા: પંચાંગ, લોકગાથાઓ, લોકકથાઓ. ઇંગ્લૅન્ડમાં **પેની ચૅપબુક્સ** (એક પેનીનાં પુસ્તકો) **ચૅપમેન** નામના ફેરિયાઓ વેચતા. ફ્રાન્સમાં ***બિબ્લિયોથેક બ્લૂ*** હલકા કાગળ પર છપાયેલાં, **વાદળી પૂંઠાં**વાળાં સસ્તાં નાનાં પુસ્તકો હતાં.\n"
  "- 18મી સદીની શરૂઆતથી **સામયિકો**માં યુદ્ધો અને વેપારના સમાચારો સાથે મનોરંજન પણ રહેતું. વૈજ્ઞાનિકો અને તત્ત્વચિંતકોના વિચારો સુલભ બન્યા: **આઇઝેક ન્યૂટન**ની શોધો છપાઈ, અને **ટૉમસ પેઇન, વૉલ્ટેર અને ઝાં ઝાક રુસો**નાં લખાણો ખૂબ છપાયાં અને વંચાયાં.\n\n"
  "**'તો જુલમીઓ, હવે ધ્રૂજો!'** 18મી સદીના મધ્ય સુધીમાં લોકો માનવા લાગ્યા કે પુસ્તકો પ્રગતિ અને જ્ઞાનોદય ફેલાવી શકે અને સમાજને આપખુદશાહીમાંથી મુક્ત કરી શકે. 18મી સદીના ફ્રેન્ચ નવલકથાકાર **લૂઈ-સેબાસ્તિયન મર્સિયે**એ જાહેર કર્યું: *'છાપખાનું પ્રગતિનું સૌથી શક્તિશાળી સાધન છે અને લોકમત એવું બળ છે જે આપખુદશાહીને ઉડાવી દેશે.'* "
  "તેમણે લખ્યું: ***'તો વિશ્વના જુલમીઓ, ધ્રૂજો! લેખકની કલમ સામે ધ્રૂજો!'*** (જુલમીઓ એટલે રાજાશાહી અને ચર્ચ જેવી નિરંકુશ સંસ્થાઓ).\n\n"
  "**મુદ્રણ સંસ્કૃતિ અને ફ્રેન્ચ ક્રાંતિ:** ઇતિહાસકારો ત્રણ દલીલો આપે છે:\n1. મુદ્રણે **જ્ઞાનોદયના ચિંતકો** (વૉલ્ટેર, રુસો)ના વિચારોને લોકપ્રિય બનાવ્યા, જેમણે પરંપરા, અંધશ્રદ્ધા અને આપખુદશાહીની ટીકા કરી અને તર્કના શાસનની હિમાયત કરી; તેમણે ચર્ચની પવિત્ર સત્તા અને રાજ્યની આપખુદ શક્તિ પર પ્રહાર કર્યો.\n"
  "2. મુદ્રણે **ચર્ચા અને સંવાદની નવી સંસ્કૃતિ** ઊભી કરી: તર્કની શક્તિથી પરિચિત જનતાએ બધાં મૂલ્યો, ધોરણો અને સંસ્થાઓનું પુનર્મૂલ્યાંકન કર્યું.\n"
  "3. **1780ના દાયકા** સુધીમાં રાજવી પરિવાર અને તેમની નૈતિકતાની મજાક ઉડાવતા સાહિત્ય, **કાર્ટૂન અને ઠઠ્ઠાચિત્રો**નો ધોધ વહ્યો, જે બતાવતાં કે રાજાશાહી ભોગવિલાસમાં ડૂબેલી છે જ્યારે સામાન્ય લોકો કષ્ટ ભોગવે છે; તેનાથી રાજાશાહી સામે શત્રુતા ફેલાઈ.\n\n"
  "પણ મુદ્રણ સીધેસીધું લોકોના વિચારો ઘડતું નથી: લોકો રાજવી અને ચર્ચનો પ્રચાર પણ વાંચતા, અને કેટલાક વિચારો સ્વીકારતા તો કેટલાક નકારતા. હા, મુદ્રણે **જુદી રીતે વિચારવાની શક્યતા** ચોક્કસ ખોલી."),

 "s5.thm.title": ("बच्चे, महिलाएँ, मज़दूर और नई तकनीक", "બાળકો, સ્ત્રીઓ, મજૂરો અને નવી ટેકનોલોજી"),
 "s5.thm.body": (
  "19वीं सदी में यूरोप में **व्यापक साक्षरता** आई, जिससे **बच्चों, महिलाओं और मज़दूरों** में बहुत-से नए पाठक बने।\n\n"
  "- **बच्चे:** 19वीं सदी के अंत से प्राथमिक शिक्षा अनिवार्य हुई, और प्रकाशकों के लिए स्कूली पाठ्यपुस्तकें महत्त्वपूर्ण हो गईं। **1857 में फ़्रांस** में **बाल-पुस्तकें** छापने के लिए एक अलग प्रेस बनी। जर्मनी के **ग्रिम बंधुओं** ने किसानों से पारंपरिक लोककथाएँ इकट्ठा करके **1812** में छापीं, और बच्चों के लिए अनुपयुक्त या अभिजात वर्ग को अश्लील लगने वाली बातें हटा दीं।\n"
  "- **महिलाएँ:** पेनी पत्रिकाएँ और आचरण तथा गृहस्थी सिखाने वाली पुस्तिकाएँ महिलाओं के लिए थीं। कुछ सबसे प्रसिद्ध उपन्यासकार महिलाएँ थीं, **जेन ऑस्टिन, ब्रॉण्टे बहनें और जॉर्ज इलियट**, जिनके लेखन ने इच्छाशक्ति, दृढ़ व्यक्तित्व और सोचने की शक्ति वाली एक नई तरह की महिला की छवि गढ़ी।\n"
  "- **मज़दूर:** 17वीं सदी से मौजूद **किराये के पुस्तकालय** सफ़ेदपोश कर्मचारियों, कारीगरों और निम्न-मध्य वर्ग को शिक्षित करने के साधन बन गए। 19वीं सदी के मध्य से काम के घंटे घटने पर मज़दूरों ने राजनीतिक पर्चे और आत्मकथाएँ लिखीं।\n\n"
  "**और नवाचार:** 18वीं सदी के अंत तक प्रेस धातु से बनने लगीं। 19वीं सदी के मध्य तक न्यूयॉर्क के **रिचर्ड एम. हो** ने **शक्ति-चालित बेलनाकार प्रेस** बना ली, जो प्रति घंटे **8,000 ताव** छाप सकती थी, अख़बारों के लिए आदर्श। 19वीं सदी के अंत में **ऑफ़सेट प्रेस** एक साथ **छह रंग** छाप सकती थी; 20वीं सदी की शुरुआत से **बिजली से चलने वाली प्रेसों** ने छपाई तेज़ कर दी।\n\n"
  "**किताबें बेचना:** पत्रिकाओं ने **उपन्यासों को धारावाहिक** रूप में छापा; 1920 के दशक में इंग्लैंड में लोकप्रिय किताबें सस्ती **शिलिंग श्रृंखला** में बिकीं; **जिल्द पर आवरण (डस्ट कवर)** 20वीं सदी का नवाचार था; और **1930 के दशक की महामंदी** में प्रकाशकों ने सस्ते **पेपरबैक** संस्करण निकाले।",
  "19મી સદીમાં યુરોપમાં **વ્યાપક સાક્ષરતા** આવી, જેથી **બાળકો, સ્ત્રીઓ અને મજૂરો**માં ઘણા નવા વાચકો બન્યા.\n\n"
  "- **બાળકો:** 19મી સદીના અંતથી પ્રાથમિક શિક્ષણ ફરજિયાત બન્યું, અને પ્રકાશકો માટે શાળાનાં પાઠ્યપુસ્તકો મહત્ત્વનાં બન્યાં. **1857માં ફ્રાન્સ**માં **બાળસાહિત્ય** છાપવા માટે અલગ પ્રેસ સ્થપાઈ. જર્મનીના **ગ્રિમ બંધુઓએ** ખેડૂતો પાસેથી પરંપરાગત લોકકથાઓ એકઠી કરીને **1812**માં છાપી, અને બાળકો માટે અયોગ્ય કે ઉચ્ચ વર્ગને અશ્લીલ લાગે તેવી બાબતો કાઢી નાખી.\n"
  "- **સ્ત્રીઓ:** પેની સામયિકો અને વર્તન તથા ઘરકામ શીખવતી પુસ્તિકાઓ સ્ત્રીઓ માટે હતી. કેટલીક સૌથી જાણીતી નવલકથાકાર સ્ત્રીઓ હતી, **જેન ઑસ્ટિન, બ્રૉન્ટે બહેનો અને જૉર્જ એલિયટ**, જેમનાં લખાણોએ ઇચ્છાશક્તિ, દૃઢ વ્યક્તિત્વ અને વિચારવાની શક્તિવાળી નવી પ્રકારની સ્ત્રીની છબી ઘડી.\n"
  "- **મજૂરો:** 17મી સદીથી અસ્તિત્વમાં રહેલાં **ભાડાનાં પુસ્તકાલયો** સફેદપોશ કર્મચારીઓ, કારીગરો અને નિમ્ન-મધ્યમ વર્ગને શિક્ષિત કરવાનાં સાધન બન્યાં. 19મી સદીના મધ્યથી કામના કલાકો ઘટતાં મજૂરોએ રાજકીય પત્રિકાઓ અને આત્મકથાઓ લખી.\n\n"
  "**વધુ નવીનતાઓ:** 18મી સદીના અંત સુધીમાં પ્રેસ ધાતુની બનવા લાગી. 19મી સદીના મધ્ય સુધીમાં ન્યૂયૉર્કના **રિચર્ડ એમ. હો**એ **શક્તિ-ચાલિત નળાકાર પ્રેસ** બનાવી, જે કલાકે **8,000 તાવ** છાપી શકતી, અખબારો માટે આદર્શ. 19મી સદીના અંતે **ઑફસેટ પ્રેસ** એકસાથે **છ રંગ** છાપી શકતી; 20મી સદીની શરૂઆતથી **વીજળીથી ચાલતી પ્રેસોએ** છાપકામ ઝડપી બનાવ્યું.\n\n"
  "**પુસ્તકો વેચવાં:** સામયિકોએ **નવલકથાઓ હપતાવાર** છાપી; 1920ના દાયકામાં ઇંગ્લૅન્ડમાં લોકપ્રિય પુસ્તકો સસ્તી **શિલિંગ શ્રેણી**માં વેચાયાં; **પૂંઠા પરનું આવરણ (ડસ્ટ કવર)** 20મી સદીની નવીનતા હતી; અને **1930ના દાયકાની મહામંદી**માં પ્રકાશકોએ સસ્તી **પેપરબૅક** આવૃત્તિઓ બહાર પાડી."),

 "s6.thm.title": ("पांडुलिपियाँ, पहले छापेख़ाने और अख़बार", "હસ્તપ્રતો, પહેલાં છાપખાનાં અને અખબારો"),
 "s6.thm.body": (
  "**मुद्रण से पहले:** भारत में संस्कृत, अरबी, फ़ारसी और विभिन्न देसी भाषाओं में **हस्तलिखित पांडुलिपियों** की बहुत पुरानी और समृद्ध परंपरा थी, जो **ताड़ के पत्तों** या हाथ से बने काग़ज़ पर नक़ल की जाती थीं और कभी-कभी सुंदर चित्रों से सजी होती थीं। पर पांडुलिपियाँ महँगी और नाज़ुक थीं, अलग-अलग लिपियों में लिखी होती थीं, और रोज़मर्रा के जीवन में ज़्यादा प्रयोग नहीं होती थीं। "
  "उपनिवेश-पूर्व बंगाल के गाँवों के प्राथमिक स्कूलों में विद्यार्थी शिक्षक के बोलकर लिखवाने से लिखना सीखते थे; कई लोग कोई पाठ पढ़े बिना ही साक्षर हो जाते थे।\n\n"
  "**भारत में मुद्रण का आना:**\n- छापाख़ाना सबसे पहले **16वीं सदी के मध्य** में **पुर्तगाली धर्मप्रचारकों** के साथ **गोवा** आया। जेसुइट पुरोहितों ने **कोंकणी** सीखी और कई पुस्तिकाएँ छापीं; **1674** तक कोंकणी और कन्नड़ में लगभग **50 किताबें** छप चुकी थीं।\n"
  "- **कैथोलिक पुरोहितों** ने **1579 में कोचीन में पहली तमिल किताब** और **1713 में पहली मलयालम किताब** छापी। **1710** तक **डच प्रोटेस्टेंट धर्मप्रचारकों** ने **32 तमिल पुस्तकें** छाप दी थीं।\n"
  "- ईस्ट इंडिया कंपनी 17वीं सदी के अंत से छापेख़ाने आयात करने लगी, पर अंग्रेज़ी प्रेस धीरे बढ़ी। **1780** से **जेम्स ऑगस्टस हिकी** ने ***बंगाल गज़ट*** का संपादन शुरू किया, एक साप्ताहिक जो ख़ुद को *'एक व्यावसायिक पत्र, जो सबके लिए खुला है पर किसी के प्रभाव में नहीं'* कहता था। वह विज्ञापन (ग़ुलामों के आयात और बिक्री के भी) और कंपनी के वरिष्ठ अधिकारियों के बारे में गपशप छापता था। "
  "इससे नाराज़ होकर गवर्नर-जनरल **वॉरेन हेस्टिंग्स** ने हिकी को सताया और सरकारी मान्यता वाले अख़बारों को बढ़ावा दिया।\n"
  "- पहला भारतीय अख़बार राममोहन राय के क़रीबी **गंगाधर भट्टाचार्य** द्वारा निकाला गया साप्ताहिक ***बंगाल गज़ट*** था।",
  "**મુદ્રણ પહેલાં:** ભારતમાં સંસ્કૃત, અરબી, ફારસી અને વિવિધ દેશી ભાષાઓમાં **હસ્તલિખિત પ્રતો**ની ખૂબ જૂની અને સમૃદ્ધ પરંપરા હતી, જે **તાડપત્રો** કે હાથબનાવટના કાગળ પર નકલ કરાતી અને ક્યારેક સુંદર ચિત્રોથી સજાવાતી. પણ હસ્તપ્રતો મોંઘી અને નાજુક હતી, જુદી જુદી લિપિઓમાં લખાતી, અને રોજિંદા જીવનમાં ઝાઝી વપરાતી ન હતી. "
  "સંસ્થાનકાળ પહેલાંના બંગાળનાં ગામડાંની પ્રાથમિક શાળાઓમાં વિદ્યાર્થીઓ શિક્ષકના બોલીને લખાવવાથી લખતાં શીખતા; ઘણા લોકો કોઈ લખાણ વાંચ્યા વિના જ સાક્ષર બનતા.\n\n"
  "**ભારતમાં મુદ્રણનું આગમન:**\n- છાપખાનું સૌથી પહેલાં **16મી સદીના મધ્યમાં** **પોર્ટુગીઝ ધર્મપ્રચારકો** સાથે **ગોવા** આવ્યું. જેસુઇટ પાદરીઓએ **કોંકણી** શીખી અને અનેક પુસ્તિકાઓ છાપી; **1674** સુધીમાં કોંકણી અને કન્નડમાં આશરે **50 પુસ્તકો** છપાઈ ચૂક્યાં હતાં.\n"
  "- **કૅથલિક પાદરીઓએ** **1579માં કોચીનમાં પહેલું તમિળ પુસ્તક** અને **1713માં પહેલું મલયાલમ પુસ્તક** છાપ્યું. **1710** સુધીમાં **ડચ પ્રૉટેસ્ટન્ટ ધર્મપ્રચારકોએ** **32 તમિળ પુસ્તકો** છાપ્યાં હતાં.\n"
  "- ઈસ્ટ ઇન્ડિયા કંપની 17મી સદીના અંતથી છાપખાનાં આયાત કરવા લાગી, પણ અંગ્રેજી પ્રેસ ધીમે વિકસી. **1780**થી **જેમ્સ ઑગસ્ટસ હિકીએ** ***બંગાળ ગૅઝેટ***નું સંપાદન શરૂ કર્યું, એક સાપ્તાહિક જે પોતાને *'સૌ માટે ખુલ્લું, પણ કોઈના પ્રભાવ હેઠળ નહિ એવું વ્યાવસાયિક પત્ર'* કહેતું. તે જાહેરાતો (ગુલામોની આયાત અને વેચાણની પણ) અને કંપનીના વરિષ્ઠ અધિકારીઓ વિશેની ગપસપ છાપતું. "
  "તેનાથી ગુસ્સે થઈને ગવર્નર-જનરલ **વૉરન હેસ્ટિંગ્સે** હિકીને હેરાન કર્યો અને સરકાર માન્ય અખબારોને પ્રોત્સાહન આપ્યું.\n"
  "- પહેલું ભારતીય અખબાર રામમોહન રાયના નિકટના **ગંગાધર ભટ્ટાચાર્યે** પ્રકાશિત કરેલું સાપ્તાહિક ***બંગાળ ગૅઝેટ*** હતું."),
 "s6.reform.title": ("धार्मिक सुधार और सार्वजनिक बहसें", "ધાર્મિક સુધારા અને જાહેર ચર્ચાઓ"),
 "s6.reform.body": (
  "19वीं सदी की शुरुआत से धार्मिक मुद्दों पर गहरी बहसें हुईं, जो सार्वजनिक रूप से और **छपाई में** लड़ी गईं। छपी पुस्तिकाओं और अख़बारों ने नए विचार फैलाए और व्यापक जनता को बहस में शामिल होने दिया।\n\n"
  "- बंगाल में सुधारकों और हिंदू रूढ़िवादियों के बीच **विधवा-दहन, एकेश्वरवाद, ब्राह्मण पुरोहितवाद और मूर्तिपूजा** पर बहस हुई, और विचार आम लोगों की रोज़मर्रा की बोलचाल की भाषा में छापे गए। **राममोहन राय** ने **1821** से ***संवाद कौमुदी*** प्रकाशित किया; हिंदू रूढ़िवादियों ने उनके विचारों का विरोध करने के लिए ***समाचार चंद्रिका*** निकाला।\n"
  "- **1822** से दो फ़ारसी अख़बार, ***जाम-ए-जहाँ नामा*** और ***शम्सुल अख़बार***, प्रकाशित हुए; उसी वर्ष गुजराती अख़बार ***बंबई समाचार*** निकला।\n"
  "- उत्तर भारत में **उलमा** मुस्लिम राजवंशों के पतन से चिंतित थे और डरते थे कि औपनिवेशिक शासक धर्मांतरण को बढ़ावा देंगे और मुस्लिम पर्सनल लॉ बदलेंगे; उन्होंने सस्ते **लिथोग्राफ़ी प्रेस** से धर्मग्रंथों के फ़ारसी और उर्दू अनुवाद और धार्मिक अख़बार छापे। **1867** में स्थापित **देवबंद सेमिनरी** ने हज़ारों **फ़तवे** छापे, जो मुसलमानों को रोज़मर्रा के जीवन में आचरण बताते थे।\n"
  "- हिंदुओं में मुद्रण ने देसी भाषाओं में धार्मिक ग्रंथ पढ़ने को बढ़ावा दिया। **तुलसीदास की *रामचरितमानस*** का पहला मुद्रित संस्करण **1810 में कलकत्ता** से निकला। 1880 के दशक से लखनऊ की **नवल किशोर प्रेस** और बंबई की **श्री वेंकटेश्वर प्रेस** ने देसी भाषाओं में अनेक धार्मिक ग्रंथ छापे।\n\n"
  "मुद्रण ने पूरे भारत के **समुदायों को जोड़ा**: अख़बार एक जगह की ख़बर दूसरी जगह पहुँचाते, जिससे **अखिल भारतीय पहचान** बनी।",
  "19મી સદીની શરૂઆતથી ધાર્મિક મુદ્દાઓ પર ગહન ચર્ચાઓ થઈ, જે જાહેરમાં અને **છાપકામમાં** લડાઈ. છાપેલી પુસ્તિકાઓ અને અખબારોએ નવા વિચારો ફેલાવ્યા અને વ્યાપક જનતાને ચર્ચામાં ભાગ લેવા દીધો.\n\n"
  "- બંગાળમાં સુધારકો અને હિંદુ રૂઢિચુસ્તો વચ્ચે **વિધવા-દહન, એકેશ્વરવાદ, બ્રાહ્મણ પુરોહિતશાહી અને મૂર્તિપૂજા** પર ચર્ચા થઈ, અને વિચારો સામાન્ય લોકોની રોજિંદી બોલચાલની ભાષામાં છપાયા. **રામમોહન રાયે** **1821**થી ***સંવાદ કૌમુદી*** પ્રકાશિત કર્યું; હિંદુ રૂઢિચુસ્તોએ તેમના વિચારોના વિરોધ માટે ***સમાચાર ચંદ્રિકા*** શરૂ કર્યું.\n"
  "- **1822**થી બે ફારસી અખબારો, ***જામ-એ-જહાંનુમા*** અને ***શમ્સુલ અખબાર***, પ્રકાશિત થયાં; તે જ વર્ષે ગુજરાતી અખબાર ***મુંબઈ સમાચાર*** શરૂ થયું.\n"
  "- ઉત્તર ભારતમાં **ઉલેમા** મુસ્લિમ રાજવંશોના પતનથી ચિંતિત હતા અને ડરતા કે સંસ્થાનવાદી શાસકો ધર્માંતરણને પ્રોત્સાહન આપશે અને મુસ્લિમ પર્સનલ લૉ બદલશે; તેમણે સસ્તી **લિથોગ્રાફી પ્રેસ**થી ધર્મગ્રંથોના ફારસી અને ઉર્દૂ અનુવાદ અને ધાર્મિક અખબારો છાપ્યાં. **1867**માં સ્થપાયેલી **દેવબંદ સેમિનરીએ** હજારો **ફતવા** છાપ્યા, જે મુસ્લિમોને રોજિંદા જીવનમાં આચરણ સમજાવતા.\n"
  "- હિંદુઓમાં મુદ્રણે દેશી ભાષાઓમાં ધાર્મિક ગ્રંથો વાંચવાને પ્રોત્સાહન આપ્યું. **તુલસીદાસના *રામચરિતમાનસ***ની પહેલી મુદ્રિત આવૃત્તિ **1810માં કલકત્તા**થી બહાર પડી. 1880ના દાયકાથી લખનૌની **નવલ કિશોર પ્રેસ** અને મુંબઈની **શ્રી વેંકટેશ્વર પ્રેસે** દેશી ભાષાઓમાં અનેક ધાર્મિક ગ્રંથો છાપ્યા.\n\n"
  "મુદ્રણે આખા ભારતના **સમુદાયોને જોડ્યા**: અખબારો એક સ્થળના સમાચાર બીજે પહોંચાડતાં, જેથી **અખિલ ભારતીય ઓળખ** ઊભી થઈ."),
 "s6.forms.title": ("प्रकाशन के नए रूप, महिलाएँ और ग़रीब", "પ્રકાશનનાં નવાં સ્વરૂપો, સ્ત્રીઓ અને ગરીબો"),
 "s6.forms.body": (
  "**नए रूप:** **उपन्यास**, गीत, कहानियाँ और सामाजिक तथा राजनीतिक विषयों पर निबंध; **दृश्य छवियाँ**: **राजा रवि वर्मा** ने व्यापक प्रसार के लिए चित्र बनाए, सस्ते प्रिंट और कैलेंडर ग़रीबों के घर भी सजाते थे, और **1870 के दशक** तक पत्रिकाओं में **कैरिकेचर और कार्टून** सामाजिक तथा राजनीतिक मुद्दों पर टिप्पणी करने लगे।\n\n"
  "**महिलाएँ और मुद्रण:** मध्यवर्गीय घरों में महिलाओं का पढ़ना बहुत बढ़ा; उदार पिता और पति महिलाओं को घर पर पढ़ाने और स्कूल भेजने लगे। रूढ़िवादी हिंदू मानते थे कि पढ़ी-लिखी लड़की विधवा हो जाएगी, और मुसलमानों को डर था कि उर्दू के रूमानी अफ़साने पढ़कर शिक्षित महिलाएँ बिगड़ जाएँगी।\n"
  "- एक रूढ़िवादी परिवार की नवविवाहिता **राशसुंदरी देवी** ने रसोई में छिपकर पढ़ना सीखा और बाद में ***आमार जीबन*** लिखी, जो **1876** में छपी, बांग्ला की पहली संपूर्ण आत्मकथा।\n"
  "- 1860 के दशक से **कैलाशबाशिनी देवी** ने लिखा कि महिलाओं को घरों में कैसे क़ैद रखा जाता और उनके साथ अन्याय होता है। 1880 के दशक में महाराष्ट्र में **ताराबाई शिंदे और पंडिता रमाबाई** ने ऊँची जाति की हिंदू महिलाओं, विशेषकर विधवाओं, के दयनीय जीवन के बारे में गहरे रोष के साथ लिखा।\n"
  "- पंजाब में **राम चड्ढा** ने महिलाओं को आज्ञाकारी पत्नी बनना सिखाने के लिए ***इस्त्री धर्म विचार*** छापा। कलकत्ता में **बटतला** नामक इलाक़ा सस्ती लोकप्रिय किताबें छापता था, और फेरीवाले इन्हें घरों तक ले जाते, जिससे महिलाएँ फ़ुरसत में पढ़ पातीं।\n\n"
  "**मुद्रण और ग़रीब:** 19वीं सदी के मद्रासी शहरों में चौराहों पर सस्ती छोटी किताबें बिकती थीं, और 20वीं सदी की शुरुआत से **सार्वजनिक पुस्तकालय** खुलने लगे। जाति-भेद मुद्रण का विषय बना: **ज्योतिबा फुले** ने ***गुलामगिरी*** (1871) में जाति-व्यवस्था के अन्याय पर लिखा; 20वीं सदी में महाराष्ट्र में **बी. आर. आंबेडकर** और मद्रास में **ई. वी. रामास्वामी नायकर (पेरियार)** ने जाति पर ज़ोरदार लिखा। "
  "कानपुर के मिल-मज़दूर **काशीबाबा** ने ***छोटे और बड़े का सवाल*** (1938) लिखकर जातीय और वर्गीय शोषण के रिश्ते को दिखाया, और **सुदर्शन चक्र** नाम से लिखने वाले कानपुर के एक और मिल-मज़दूर की कविताएँ ***सच्ची कविताएँ*** में छपीं। 1930 के दशक तक **बंगलौर** के सूती मिल-मज़दूरों ने बंबई के मज़दूरों से प्रेरणा लेकर पुस्तकालय बनाए।",
  "**નવાં સ્વરૂપો:** **નવલકથા**, ગીતો, ટૂંકી વાર્તાઓ અને સામાજિક તથા રાજકીય વિષયો પર નિબંધો; **દૃશ્ય છબીઓ**: **રાજા રવિ વર્મા**એ વ્યાપક પ્રસાર માટે ચિત્રો બનાવ્યાં, સસ્તાં છાપેલાં ચિત્રો અને કૅલેન્ડર ગરીબોનાં ઘર પણ સજાવતાં, અને **1870ના દાયકા** સુધીમાં સામયિકોમાં **ઠઠ્ઠાચિત્રો અને કાર્ટૂન** સામાજિક તથા રાજકીય મુદ્દાઓ પર ટિપ્પણી કરવા લાગ્યાં.\n\n"
  "**સ્ત્રીઓ અને મુદ્રણ:** મધ્યમવર્ગીય ઘરોમાં સ્ત્રીઓનું વાંચન ખૂબ વધ્યું; ઉદાર પિતા અને પતિઓ સ્ત્રીઓને ઘરે ભણાવવા અને શાળાએ મોકલવા લાગ્યા. રૂઢિચુસ્ત હિંદુઓ માનતા કે ભણેલી છોકરી વિધવા બનશે, અને મુસ્લિમોને ડર હતો કે ઉર્દૂની રોમાંચક વાર્તાઓ વાંચીને શિક્ષિત સ્ત્રીઓ બગડશે.\n"
  "- એક રૂઢિચુસ્ત કુટુંબની નવપરિણીતા **રાસસુંદરી દેવીએ** રસોડામાં છુપાઈને વાંચતાં શીખ્યું અને પછીથી ***આમાર જીબન*** લખી, જે **1876**માં છપાઈ, બંગાળીની પહેલી સંપૂર્ણ આત્મકથા.\n"
  "- 1860ના દાયકાથી **કૈલાશબાશિની દેવીએ** લખ્યું કે સ્ત્રીઓને ઘરોમાં કેવી રીતે કેદ રખાય છે અને તેમની સાથે અન્યાય થાય છે. 1880ના દાયકામાં મહારાષ્ટ્રમાં **તારાબાઈ શિંદે અને પંડિતા રમાબાઈએ** ઉચ્ચ જ્ઞાતિની હિંદુ સ્ત્રીઓ, ખાસ કરીને વિધવાઓના, દયનીય જીવન વિશે ઊંડા રોષ સાથે લખ્યું.\n"
  "- પંજાબમાં **રામ ચડ્ઢાએ** સ્ત્રીઓને આજ્ઞાંકિત પત્ની બનતાં શીખવવા ***ઇસ્ત્રી ધર્મ વિચાર*** છાપ્યું. કલકત્તામાં **બટતલા** નામનો વિસ્તાર સસ્તાં લોકપ્રિય પુસ્તકો છાપતો, અને ફેરિયાઓ તે ઘરો સુધી લઈ જતા, જેથી સ્ત્રીઓ ફુરસદમાં વાંચી શકતી.\n\n"
  "**મુદ્રણ અને ગરીબો:** 19મી સદીનાં મદ્રાસી નગરોમાં ચોરાહે સસ્તાં નાનાં પુસ્તકો વેચાતાં, અને 20મી સદીની શરૂઆતથી **જાહેર પુસ્તકાલયો** ખૂલવા લાગ્યાં. જ્ઞાતિભેદ મુદ્રણનો વિષય બન્યો: **જ્યોતિબા ફુલેએ** ***ગુલામગીરી*** (1871)માં જ્ઞાતિવ્યવસ્થાના અન્યાય પર લખ્યું; 20મી સદીમાં મહારાષ્ટ્રમાં **બી. આર. આંબેડકરે** અને મદ્રાસમાં **ઈ. વી. રામાસ્વામી નાયકર (પેરિયાર)**એ જ્ઞાતિ પર જોરદાર લખ્યું. "
  "કાનપુરના મિલ-મજૂર **કાશીબાબાએ** ***છોટે ઔર બડે કા સવાલ*** (1938) લખીને જ્ઞાતિ અને વર્ગના શોષણ વચ્ચેનો સંબંધ બતાવ્યો, અને **સુદર્શન ચક્ર** નામે લખતા કાનપુરના બીજા એક મિલ-મજૂરની કવિતાઓ ***સચ્ચી કવિતાએં***માં છપાઈ. 1930ના દાયકા સુધીમાં **બેંગલોર**ના સુતરાઉ મિલ-મજૂરોએ મુંબઈના મજૂરોથી પ્રેરાઈને પુસ્તકાલયો સ્થાપ્યાં."),
 "s6.censor.title": ("मुद्रण और प्रतिबंध (सेंसरशिप)", "મુદ્રણ અને સેન્સરશિપ"),
 "s6.censor.body": (
  "- **1798** से पहले कंपनी सेंसरशिप को लेकर ज़्यादा चिंतित नहीं थी; उसके शुरुआती नियंत्रण भारत में रहने वाले उन **अंग्रेज़ों** के विरुद्ध थे जो कंपनी के कुशासन की आलोचना करते थे, क्योंकि ऐसी आलोचना का प्रयोग इंग्लैंड में उसके व्यापारिक एकाधिकार पर हमले के लिए हो सकता था।\n"
  "- **1820 के दशक** तक कलकत्ता सुप्रीम कोर्ट ने प्रेस की आज़ादी पर नियंत्रण के नियम बनाए, और कंपनी ने ब्रिटिश शासन का गुणगान करने वाले अख़बारों को बढ़ावा दिया।\n"
  "- **1835** में संपादकों की याचिकाओं पर गवर्नर-जनरल **बेंटिक** प्रेस क़ानूनों में संशोधन को राज़ी हुए, और **टॉमस मैकॉले** ने ऐसे नियम बनाए जिनसे पुरानी आज़ादी बहाल हुई।\n"
  "- **1857 के विद्रोह** के बाद रवैया बदल गया। नाराज़ अंग्रेज़ों ने 'देसी' प्रेस पर अंकुश की माँग की। जैसे-जैसे देसी अख़बार मुखर रूप से राष्ट्रवादी होते गए, सरकार ने **1878 में वर्नाक्युलर प्रेस एक्ट** पास किया, जो **आयरिश प्रेस क़ानूनों पर आधारित** था। इससे सरकार को देसी भाषाओं के अख़बारों की रिपोर्टों और संपादकीयों को **सेंसर** करने का व्यापक अधिकार मिल गया। "
  "यदि कोई रिपोर्ट **राजद्रोही** लगती, तो अख़बार को चेतावनी दी जाती; चेतावनी की अनदेखी होने पर प्रेस को **ज़ब्त** और छपाई की मशीनें **क़ब्ज़े में** ली जा सकती थीं।\n"
  "- इसके बावजूद पूरे भारत में राष्ट्रवादी अख़बार बढ़ते गए। **1907** में पंजाब के क्रांतिकारियों को निर्वासित किए जाने पर **बालगंगाधर तिलक** ने अपने अख़बार ***केसरी*** में उनके प्रति गहरी सहानुभूति के साथ लिखा। इसके कारण **1908 में उन्हें क़ैद** कर लिया गया, जिससे पूरे भारत में व्यापक विरोध हुए।",
  "- **1798** પહેલાં કંપની સેન્સરશિપ બાબતે ઝાઝી ચિંતિત ન હતી; તેનાં શરૂઆતનાં નિયંત્રણો ભારતમાં રહેતા એવા **અંગ્રેજો** સામે હતાં જે કંપનીના કુશાસનની ટીકા કરતા, કારણ કે આવી ટીકાનો ઉપયોગ ઇંગ્લૅન્ડમાં તેના વેપારી ઇજારા પર હુમલા માટે થઈ શકે.\n"
  "- **1820ના દાયકા** સુધીમાં કલકત્તા સુપ્રીમ કોર્ટે અખબારી સ્વતંત્રતા પર નિયંત્રણના નિયમો ઘડ્યા, અને કંપનીએ બ્રિટિશ શાસનનો મહિમા કરતાં અખબારોને પ્રોત્સાહન આપ્યું.\n"
  "- **1835**માં તંત્રીઓની અરજીઓ પર ગવર્નર-જનરલ **બેન્ટિક** અખબારી કાયદાઓમાં સુધારા માટે સંમત થયા, અને **ટૉમસ મેકૉલે**એ એવા નિયમો ઘડ્યા જેથી જૂની સ્વતંત્રતા પાછી મળી.\n"
  "- **1857ના વિપ્લવ** પછી વલણ બદલાયું. ગુસ્સે થયેલા અંગ્રેજોએ 'દેશી' પ્રેસ પર અંકુશની માગણી કરી. દેશી અખબારો જેમ જેમ સ્પષ્ટપણે રાષ્ટ્રવાદી બનતાં ગયાં, તેમ સરકારે **1878માં વર્નાક્યુલર પ્રેસ ઍક્ટ** પસાર કર્યો, જે **આઇરિશ પ્રેસ કાયદાઓ પર આધારિત** હતો. તેનાથી સરકારને દેશી ભાષાનાં અખબારોના અહેવાલો અને તંત્રીલેખોને **સેન્સર** કરવાનો વ્યાપક અધિકાર મળ્યો. "
  "જો કોઈ અહેવાલ **રાજદ્રોહી** લાગે, તો અખબારને ચેતવણી અપાતી; ચેતવણીની અવગણના થાય તો પ્રેસ **જપ્ત** અને છાપવાનાં યંત્રો **કબજે** લઈ શકાતાં.\n"
  "- છતાં આખા ભારતમાં રાષ્ટ્રવાદી અખબારો વધતાં ગયાં. **1907**માં પંજાબના ક્રાંતિકારીઓને દેશનિકાલ કરાયા ત્યારે **બાળ ગંગાધર ટિળકે** પોતાના અખબાર ***કેસરી***માં તેમના પ્રત્યે ઊંડી સહાનુભૂતિથી લખ્યું. તેના કારણે **1908માં તેમને કેદ** કરાયા, જેથી આખા ભારતમાં વ્યાપક વિરોધ થયો."),
 "s6.laws.title": ("औपनिवेशिक भारत में प्रेस नीति कैसे बदली", "સંસ્થાનવાદી ભારતમાં અખબારી નીતિ કેવી રીતે બદલાઈ"),
 "s6.laws.body": (
  "| वर्ष | औपनिवेशिक भारत में प्रेस नीति |\n|---|---|\n| 1798 से पहले | बहुत कम सेंसरशिप; शुरुआती नियंत्रण कंपनी की आलोचना करने वाले अंग्रेज़ों के विरुद्ध |\n| 1820 का दशक | कलकत्ता सुप्रीम कोर्ट के नियम प्रेस की आज़ादी पर नियंत्रण करते हैं; ब्रिटिश-समर्थक अख़बारों को बढ़ावा |\n"
  "| 1835 | बेंटिक प्रेस क़ानून बदलने को राज़ी; मैकॉले के नियमों से पुरानी आज़ादी बहाल |\n| 1857 के बाद | 'देसी' प्रेस पर अंकुश की माँग |\n"
  "| 1878 | **वर्नाक्युलर प्रेस एक्ट** (आयरिश प्रेस क़ानूनों पर आधारित): देसी अख़बारों को सेंसर करने का व्यापक अधिकार; प्रेस ज़ब्त की जा सकती थी |\n| 1908 | *केसरी* में लिखने के कारण तिलक को क़ैद |",
  "| વર્ષ | સંસ્થાનવાદી ભારતમાં અખબારી નીતિ |\n|---|---|\n| 1798 પહેલાં | ખૂબ ઓછી સેન્સરશિપ; શરૂઆતનાં નિયંત્રણો કંપનીની ટીકા કરતા અંગ્રેજો સામે |\n| 1820નો દાયકો | કલકત્તા સુપ્રીમ કોર્ટના નિયમો અખબારી સ્વતંત્રતા પર નિયંત્રણ મૂકે છે; બ્રિટિશ-તરફી અખબારોને પ્રોત્સાહન |\n"
  "| 1835 | બેન્ટિક અખબારી કાયદા બદલવા સંમત; મેકૉલેના નિયમોથી જૂની સ્વતંત્રતા પાછી |\n| 1857 પછી | 'દેશી' પ્રેસ પર અંકુશની માગણી |\n"
  "| 1878 | **વર્નાક્યુલર પ્રેસ ઍક્ટ** (આઇરિશ પ્રેસ કાયદાઓ પર આધારિત): દેશી અખબારોને સેન્સર કરવાનો વ્યાપક અધિકાર; પ્રેસ જપ્ત થઈ શકતી |\n| 1908 | *કેસરી*માં લખવાને કારણે ટિળકને કેદ |"),
 "s6.timeline.title": ("अध्याय की समयरेखा", "પ્રકરણની સમયરેખા"),
 "s6.timeline.body": (
  "| वर्ष | घटना |\n|---|---|\n| 594 ई. | चीन में काठ के ब्लॉकों से किताबें छपीं |\n| 768–770 ई. | बौद्ध प्रचारक हाथ की छपाई जापान लाए |\n| 868 ई. | *डायमंड सूत्र*, सबसे पुरानी छपी जापानी किताब |\n"
  "| 1295 | मार्को पोलो काठ की छपाई की जानकारी लेकर इटली लौटे |\n| 1448 | गुटेनबर्ग ने छापाख़ाना पूरा किया; बाइबिल छापी |\n| 1517 | मार्टिन लूथर की पिच्चानवे स्थापनाएँ |\n| 1558 | रोमन चर्च की प्रतिबंधित किताबों की सूची |\n"
  "| 16वीं सदी का मध्य | भारत में पहला छापाख़ाना, गोवा में (पुर्तगाली धर्मप्रचारक) |\n| 1579 / 1713 | पहली तमिल किताब (कोचीन) / पहली मलयालम किताब |\n| 1780 | जेम्स ऑगस्टस हिकी का *बंगाल गज़ट* |\n"
  "| 1821 | राममोहन राय का *संवाद कौमुदी* |\n| 1822 | *बंबई समाचार* (गुजराती); फ़ारसी अख़बार *जाम-ए-जहाँ नामा* और *शम्सुल अख़बार* |\n| 1835 | बेंटिक और मैकॉले ने प्रेस की आज़ादी बहाल की |\n"
  "| 1867 | देवबंद सेमिनरी की स्थापना |\n| 1876 | राशसुंदरी देवी की *आमार जीबन* |\n| 1878 | वर्नाक्युलर प्रेस एक्ट |\n| 1908 | *केसरी* में लिखने के लिए तिलक को क़ैद |",
  "| વર્ષ | ઘટના |\n|---|---|\n| ઈ.સ. 594 | ચીનમાં લાકડાના બ્લૉકથી પુસ્તકો છપાયાં |\n| ઈ.સ. 768–770 | બૌદ્ધ પ્રચારકો હાથનું છાપકામ જાપાન લાવ્યા |\n| ઈ.સ. 868 | *ડાયમંડ સૂત્ર*, સૌથી જૂનું છપાયેલું જાપાની પુસ્તક |\n"
  "| 1295 | માર્કો પોલો લાકડાના છાપકામની જાણકારી લઈ ઇટાલી પાછા ફર્યા |\n| 1448 | ગુટેનબર્ગે છાપખાનું પૂર્ણ કર્યું; બાઇબલ છાપ્યું |\n| 1517 | માર્ટિન લ્યૂથરના પંચાણું સિદ્ધાંતો |\n| 1558 | રોમન ચર્ચની પ્રતિબંધિત પુસ્તકોની યાદી |\n"
  "| 16મી સદીનો મધ્ય | ભારતમાં પહેલું છાપખાનું, ગોવામાં (પોર્ટુગીઝ ધર્મપ્રચારકો) |\n| 1579 / 1713 | પહેલું તમિળ પુસ્તક (કોચીન) / પહેલું મલયાલમ પુસ્તક |\n| 1780 | જેમ્સ ઑગસ્ટસ હિકીનું *બંગાળ ગૅઝેટ* |\n"
  "| 1821 | રામમોહન રાયનું *સંવાદ કૌમુદી* |\n| 1822 | *મુંબઈ સમાચાર* (ગુજરાતી); ફારસી અખબારો *જામ-એ-જહાંનુમા* અને *શમ્સુલ અખબાર* |\n| 1835 | બેન્ટિક અને મેકૉલેએ અખબારી સ્વતંત્રતા પાછી આપી |\n"
  "| 1867 | દેવબંદ સેમિનરીની સ્થાપના |\n| 1876 | રાસસુંદરી દેવીની *આમાર જીબન* |\n| 1878 | વર્નાક્યુલર પ્રેસ ઍક્ટ |\n| 1908 | *કેસરી*માં લખવા બદલ ટિળકને કેદ |"),

 "s7.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s7.memory.body": (
  "- **पूर्वी एशिया: चीन 594, जापान 768–770, डायमंड सूत्र 868।**\n- **यूरोप: \"काग़ज़ → पोलो → गुटेनबर्ग → लूथर\":** 11वीं सदी में काग़ज़, 1295 मार्को पोलो, 1448 गुटेनबर्ग की बाइबिल, 1517 लूथर की स्थापनाएँ।\n"
  "- **गुटेनबर्ग के तीन हुनर = 3 औज़ार:** जैतून की प्रेस (प्रेस), सुनार (बारीकी), सीसे के साँचे (धातु के टाइप)।\n- **भारत में पहली बार: गोवा प्रेस → तमिल 1579 → मलयालम 1713 → हिकी 1780 → संवाद कौमुदी 1821 → बंबई समाचार 1822।**\n"
  "- **सेंसरशिप: 1835 आज़ादी (मैकॉले), 1878 पाबंदी (वर्नाक्युलर प्रेस एक्ट), 1908 तिलक को क़ैद।**",
  "- **પૂર્વ એશિયા: ચીન 594, જાપાન 768–770, ડાયમંડ સૂત્ર 868.**\n- **યુરોપ: \"કાગળ → પોલો → ગુટેનબર્ગ → લ્યૂથર\":** 11મી સદીમાં કાગળ, 1295 માર્કો પોલો, 1448 ગુટેનબર્ગનું બાઇબલ, 1517 લ્યૂથરના સિદ્ધાંતો.\n"
  "- **ગુટેનબર્ગનાં ત્રણ કૌશલ્ય = 3 સાધનો:** ઑલિવની પ્રેસ (પ્રેસ), સોની (ચોકસાઈ), સીસાનાં બીબાં (ધાતુના ટાઇપ).\n- **ભારતમાં પહેલી વાર: ગોવા પ્રેસ → તમિળ 1579 → મલયાલમ 1713 → હિકી 1780 → સંવાદ કૌમુદી 1821 → મુંબઈ સમાચાર 1822.**\n"
  "- **સેન્સરશિપ: 1835 સ્વતંત્રતા (મેકૉલે), 1878 પ્રતિબંધ (વર્નાક્યુલર પ્રેસ ઍક્ટ), 1908 ટિળકને કેદ.**"),
 "s7.mistakes.title": ("सामान्य गलतियाँ", "સામાન્ય ભૂલો"),
 "s7.mistakes.body": (
  "1. कहना कि मुद्रण यूरोप में शुरू हुआ: यह **चीन, जापान और कोरिया** में शुरू हुआ।\n2. कहना कि गुटेनबर्ग की पहली किताब उपन्यास थी: वह **बाइबिल** थी (तीन साल में लगभग 180 प्रतियाँ)।\n"
  "3. **हिकी** के बंगाल गज़ट (अंग्रेज़ी, 1780) और **गंगाधर भट्टाचार्य** के बंगाल गज़ट (पहला भारतीय अख़बार) को मिला देना।\n4. कहना कि वर्नाक्युलर प्रेस एक्ट ब्रिटिश क़ानूनों पर आधारित था: यह **आयरिश** प्रेस क़ानूनों पर आधारित था।\n"
  "5. कहना कि मैकॉले ने प्रेस पर रोक लगाई: उन्होंने 1835 में आज़ादी **बहाल** की।\n6. *संवाद कौमुदी* (राममोहन राय) और *समाचार चंद्रिका* (उनके रूढ़िवादी विरोधी) को मिला देना।",
  "1. કહેવું કે મુદ્રણ યુરોપમાં શરૂ થયું: તે **ચીન, જાપાન અને કોરિયા**માં શરૂ થયું.\n2. કહેવું કે ગુટેનબર્ગનું પહેલું પુસ્તક નવલકથા હતું: તે **બાઇબલ** હતું (ત્રણ વર્ષમાં આશરે 180 નકલો).\n"
  "3. **હિકી**ના બંગાળ ગૅઝેટ (અંગ્રેજી, 1780) અને **ગંગાધર ભટ્ટાચાર્ય**ના બંગાળ ગૅઝેટ (પહેલું ભારતીય અખબાર)ને ભેળવી દેવાં.\n4. કહેવું કે વર્નાક્યુલર પ્રેસ ઍક્ટ બ્રિટિશ કાયદાઓ પર આધારિત હતો: તે **આઇરિશ** પ્રેસ કાયદાઓ પર આધારિત હતો.\n"
  "5. કહેવું કે મેકૉલેએ પ્રેસ પર પ્રતિબંધ મૂક્યો: તેમણે 1835માં સ્વતંત્રતા **પાછી આપી**.\n6. *સંવાદ કૌમુદી* (રામમોહન રાય) અને *સમાચાર ચંદ્રિકા* (તેમના રૂઢિચુસ્ત વિરોધીઓ)ને ભેળવી દેવાં."),
 "s7.tip.title": ("कक्षा में करके देखिए", "વર્ગમાં કરી જુઓ"),
 "s7.tip.body": ("आलू या रबड़ की मोहर से एक 'काठ-छपाई' बनाइए, फिर विद्यार्थियों से एक पन्ना हाथ से नक़ल करवाइए और लगे समय की तुलना कीजिए। "
                 "फिर 1820 के दशक की एक बहस का अभिनय कराइए: एक समूह *संवाद कौमुदी* के लिए पर्चा लिखे, दूसरा *समाचार चंद्रिका* के लिए, और कक्षा देखे कि मुद्रण ने एक बहस को सार्वजनिक बहस कैसे बना दिया।",
                 "બટાકા કે રબરના સિક્કાથી એક 'લાકડાનું છાપકામ' બનાવો, પછી વિદ્યાર્થીઓ પાસે એક પાનું હાથથી નકલ કરાવો અને લાગેલા સમયની સરખામણી કરો. "
                 "પછી 1820ના દાયકાની એક ચર્ચાનો અભિનય કરાવો: એક જૂથ *સંવાદ કૌમુદી* માટે પત્રિકા લખે, બીજું *સમાચાર ચંદ્રિકા* માટે, અને વર્ગ જુએ કે મુદ્રણે એક ચર્ચાને જાહેર ચર્ચા કેવી રીતે બનાવી."),
 "s7.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s7.reflection.body": ("मर्सिए मानते थे कि छापाख़ाना निरंकुशता को उड़ा देगा। क्या आपके विचार से आज सोशल मीडिया वैसी ही भूमिका निभाता है? एक तरीक़ा बताइए जिसमें ऐसा है और एक जिसमें नहीं।", "મર્સિયે માનતા કે છાપખાનું આપખુદશાહીને ઉડાવી દેશે. શું તમારા મતે આજે સોશિયલ મીડિયા એવી જ ભૂમિકા ભજવે છે? એક રીત જણાવો જેમાં એવું છે અને એક જેમાં નથી."),
 "s7.connection.title": ("यह कहाँ ले जाता है", "આ ક્યાં લઈ જાય છે"),
 "s7.connection.body": (
  "- **अध्याय 1:** मुद्रण ने यूरोप में राष्ट्रवाद और उदारवाद के विचार फैलाए।\n- **अध्याय 2:** राष्ट्रवादी अख़बारों, गीतों और चित्रों ने भारत में सामूहिक अपनेपन का भाव बनाया।\n"
  "- **राजनीति विज्ञान, लोकतंत्र के परिणाम:** जवाबदेह सरकार के लिए स्वतंत्र प्रेस ज़रूरी है।",
  "- **પ્રકરણ 1:** મુદ્રણે યુરોપમાં રાષ્ટ્રવાદ અને ઉદારમતવાદના વિચારો ફેલાવ્યા.\n- **પ્રકરણ 2:** રાષ્ટ્રવાદી અખબારો, ગીતો અને ચિત્રોએ ભારતમાં સામૂહિક સંબંધની ભાવના ઊભી કરી.\n"
  "- **રાજ્યશાસ્ત્ર, લોકશાહીનાં પરિણામો:** જવાબદાર સરકાર માટે સ્વતંત્ર પ્રેસ જરૂરી છે."),
 "s7.mastery.title": ("निपुणता चुनौती", "નિપુણતા પડકાર"),
 "s7.mastery.body": (
  "'मुद्रण ने अलग ढंग से सोचने की संभावना खोल दी।' यूरोप और भारत के संदर्भ में लगभग 120 शब्दों में समझाइए।\n\n"
  "**आदर्श उत्तर:** यूरोप में लूथर की पिच्चानवे स्थापनाएँ (1517) छपकर व्यापक रूप से पढ़ी गईं, जिससे चर्च में फूट पड़ी और धर्मसुधार शुरू हुआ; मेनोकियो ने किताबें पढ़कर बाइबिल की नई व्याख्या की; वॉल्तेयर और रूसो के लेखों ने तर्क के शासन का विचार फैलाया, और फ़्रांसीसी क्रांति से पहले कार्टूनों ने राजशाही का मज़ाक़ उड़ाया। "
  "भारत में राममोहन राय के संवाद कौमुदी और रूढ़िवादी समाचार चंद्रिका ने समाज सुधार को सार्वजनिक बहस बना दिया; राशसुंदरी देवी और पंडिता रमाबाई जैसी महिलाओं ने महिलाओं के कष्टों पर लिखा; फुले और आंबेडकर ने जाति पर प्रहार किया; तिलक के केसरी जैसे राष्ट्रवादी अख़बारों ने औपनिवेशिक शासन की आलोचना की। "
  "मुद्रण ने यह तय नहीं किया कि लोग क्या सोचें, पर इसने उन्हें प्रश्न करने और बहस करने दिया।",
  "'મુદ્રણે જુદી રીતે વિચારવાની શક્યતા ખોલી.' યુરોપ અને ભારતના સંદર્ભમાં આશરે 120 શબ્દોમાં સમજાવો.\n\n"
  "**આદર્શ જવાબ:** યુરોપમાં લ્યૂથરના પંચાણું સિદ્ધાંતો (1517) છપાઈને વ્યાપક રીતે વંચાયા, જેથી ચર્ચમાં ફાટ પડી અને ધર્મસુધારણા શરૂ થઈ; મેનોકિયોએ પુસ્તકો વાંચીને બાઇબલનું નવું અર્થઘટન કર્યું; વૉલ્ટેર અને રુસોનાં લખાણોએ તર્કના શાસનનો વિચાર ફેલાવ્યો, અને ફ્રેન્ચ ક્રાંતિ પહેલાં કાર્ટૂનોએ રાજાશાહીની મજાક ઉડાવી. "
  "ભારતમાં રામમોહન રાયના સંવાદ કૌમુદી અને રૂઢિચુસ્ત સમાચાર ચંદ્રિકાએ સમાજસુધારાને જાહેર ચર્ચા બનાવી; રાસસુંદરી દેવી અને પંડિતા રમાબાઈ જેવી સ્ત્રીઓએ સ્ત્રીઓનાં કષ્ટો પર લખ્યું; ફુલે અને આંબેડકરે જ્ઞાતિ પર પ્રહાર કર્યો; ટિળકના કેસરી જેવાં રાષ્ટ્રવાદી અખબારોએ સંસ્થાનવાદી શાસનની ટીકા કરી. "
  "મુદ્રણે એ નક્કી ન કર્યું કે લોકો શું વિચારે, પણ તેણે તેમને પ્રશ્ન કરવા અને ચર્ચા કરવા દીધા."),
 "s7.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s7.summary.body": (
  "- मुद्रण चीन में शुरू हुआ (594 ई. से काठ के ब्लॉक), जापान पहुँचा (768–770 ई.; डायमंड सूत्र, 868) और काग़ज़ तथा मार्को पोलो (1295) के ज़रिए यूरोप पहुँचा।\n"
  "- गुटेनबर्ग ने 1448 तक छापाख़ाना पूरा किया (बाइबिल); छापेख़ाने पूरे यूरोप में फैले, जिससे मुद्रण क्रांति आई।\n"
  "- मुद्रण से नया पाठक वर्ग, धार्मिक बहस और असहमति (लूथर, मेनोकियो), पढ़ने का जुनून और फ़्रांसीसी क्रांति के पीछे के विचार आए।\n"
  "- 19वीं सदी में बच्चे, महिलाएँ और मज़दूर पाठक बने; नई प्रेसें (हो की बेलनाकार प्रेस, ऑफ़सेट प्रेस) और बिक्री के नए तरीक़े आए।\n"
  "- भारत में मुद्रण 16वीं सदी के मध्य में गोवा आया; अख़बारों और पुस्तिकाओं ने धार्मिक सुधार की बहसें फैलाईं, समुदायों को जोड़ा, महिलाओं और निचली जातियों को आवाज़ दी, और औपनिवेशिक सेंसरशिप (वर्नाक्युलर प्रेस एक्ट, 1878) को जन्म दिया।",
  "- મુદ્રણ ચીનમાં શરૂ થયું (ઈ.સ. 594થી લાકડાના બ્લૉક), જાપાન પહોંચ્યું (ઈ.સ. 768–770; ડાયમંડ સૂત્ર, 868) અને કાગળ તથા માર્કો પોલો (1295) દ્વારા યુરોપ પહોંચ્યું.\n"
  "- ગુટેનબર્ગે 1448 સુધીમાં છાપખાનું પૂર્ણ કર્યું (બાઇબલ); છાપખાનાં આખા યુરોપમાં ફેલાયાં, જેથી મુદ્રણ ક્રાંતિ આવી.\n"
  "- મુદ્રણથી નવો વાચકવર્ગ, ધાર્મિક ચર્ચા અને અસંમતિ (લ્યૂથર, મેનોકિયો), વાંચનનો જુવાળ અને ફ્રેન્ચ ક્રાંતિ પાછળના વિચારો આવ્યા.\n"
  "- 19મી સદીમાં બાળકો, સ્ત્રીઓ અને મજૂરો વાચકો બન્યા; નવી પ્રેસો (હોની નળાકાર પ્રેસ, ઑફસેટ પ્રેસ) અને વેચાણની નવી રીતો આવી.\n"
  "- ભારતમાં મુદ્રણ 16મી સદીના મધ્યમાં ગોવા આવ્યું; અખબારો અને પુસ્તિકાઓએ ધાર્મિક સુધારાની ચર્ચાઓ ફેલાવી, સમુદાયોને જોડ્યા, સ્ત્રીઓ અને નીચલી જ્ઞાતિઓને અવાજ આપ્યો, અને સંસ્થાનવાદી સેન્સરશિપ (વર્નાક્યુલર પ્રેસ ઍક્ટ, 1878)ને જન્મ આપ્યો."),
 "s7.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટે સૂચનો"),
 "s7.examtips.body": (
  "- 2025-26 के नमूना प्रश्न-पत्र में मर्सिए के 'निरंकुशवादियों' पर MCQ और 19वीं सदी में अख़बार क्यों छपे और लोकप्रिय हुए, इस पर केस स्टडी पूछी गई।\n"
  "- 3/5 अंक के प्रश्न: गुटेनबर्ग की प्रेस, लूथर और धर्मसुधार, मुद्रण और फ़्रांसीसी क्रांति, वर्नाक्युलर प्रेस एक्ट, महिलाएँ और मुद्रण, भारत में मुद्रण और धार्मिक सुधार।\n"
  "- छोटे उद्धरण सही लिखिए: लूथर का 'ईश्वर की महानतम देन', हिकी का 'सबके लिए खुला, पर किसी के प्रभाव में नहीं'।",
  "- 2025-26ના નમૂના પ્રશ્નપત્રમાં મર્સિયેના 'જુલમીઓ' પર MCQ અને 19મી સદીમાં અખબારો કેમ છપાયાં અને લોકપ્રિય બન્યાં, તેના પર કેસ સ્ટડી પુછાયાં.\n"
  "- 3/5 ગુણના પ્રશ્નો: ગુટેનબર્ગની પ્રેસ, લ્યૂથર અને ધર્મસુધારણા, મુદ્રણ અને ફ્રેન્ચ ક્રાંતિ, વર્નાક્યુલર પ્રેસ ઍક્ટ, સ્ત્રીઓ અને મુદ્રણ, ભારતમાં મુદ્રણ અને ધાર્મિક સુધારા.\n"
  "- ટૂંકાં અવતરણો સાચાં લખો: લ્યૂથરનું 'ઈશ્વરની સૌથી મોટી ભેટ', હિકીનું 'સૌ માટે ખુલ્લું, પણ કોઈના પ્રભાવ હેઠળ નહિ'."),
 "s7.flash1.front": ("गुटेनबर्ग ने पहली बार कब और क्या छापा?", "ગુટેનબર્ગે પહેલી વાર ક્યારે અને શું છાપ્યું?"),
 "s7.flash1.back": ("बाइबिल: लगभग 180 प्रतियाँ, 1448 तक प्रणाली पूरी, तीन साल लगे।", "બાઇબલ: આશરે 180 નકલો, 1448 સુધીમાં પદ્ધતિ પૂર્ણ, ત્રણ વર્ષ લાગ્યાં."),
 "s7.flash2.front": ("वर्नाक्युलर प्रेस एक्ट (1878) किस बात की अनुमति देता था?", "વર્નાક્યુલર પ્રેસ ઍક્ટ (1878) શાની છૂટ આપતો હતો?"),
 "s7.flash2.back": ("देसी अख़बारों की सेंसरशिप; राजद्रोही रिपोर्ट की चेतावनी की अनदेखी पर प्रेस ज़ब्त करना।", "દેશી અખબારોની સેન્સરશિપ; રાજદ્રોહી અહેવાલની ચેતવણીની અવગણના થાય તો પ્રેસ જપ્ત કરવી."),
 "s7.flash3.front": ("'आमार जीबन' किसने लिखी और यह क्यों महत्त्वपूर्ण है?", "'આમાર જીબન' કોણે લખી અને તે કેમ મહત્ત્વની છે?"),
 "s7.flash3.back": ("राशसुंदरी देवी (1876): बांग्ला की पहली संपूर्ण आत्मकथा।", "રાસસુંદરી દેવી (1876): બંગાળીની પહેલી સંપૂર્ણ આત્મકથા."),
 "s7.flash4.front": ("प्रतिबंधित किताबों की सूची क्या थी?", "પ્રતિબંધિત પુસ્તકોની યાદી શું હતી?"),
 "s7.flash4.back": ("1558 से रोमन कैथोलिक चर्च द्वारा रखी गई प्रतिबंधित किताबों की सूची।", "1558થી રોમન કૅથલિક ચર્ચે રાખેલી પ્રતિબંધિત પુસ્તકોની યાદી."),
}
